// Junta a todo el equipo en un solo elemento para que la IA escriba todas las observaciones de una vez.
const filas = $input.all().map((i) => i.json).filter((f) => f.usuario_id);
if (!filas.length) return [];
return [{ json: { filas, datos: JSON.stringify(filas) } }];

// Una fila por colaborador con nombres de columna en español (para Google Sheets y el Excel).
const filas = $('Juntar equipo').first().json.filas;
const s = String($input.first().json.text || '').replace(/```(json)?/gi, '');
let obs = [];
try {
  obs = JSON.parse(s.slice(s.indexOf('['), s.lastIndexOf(']') + 1));
} catch (e) {
  obs = [];
}
const porId = Object.fromEntries(obs.map((o) => [String(o.usuario_id), o.observacion]));
const frac = (a, b) => (Number(b) ? `${a}/${b}` : '—');

return filas.map((f) => ({
  json: {
    'Semana del': String(f.semana_del).slice(0, 10),
    'Colaborador': f.nombre,
    'Días con registro': frac(f.dias_con_registro, f.dias_habiles),
    'Cerradas': Number(f.cerradas),
    'Abiertas': Number(f.abiertas),
    'Vencidas': Number(f.vencidas),
    'Bloqueos abiertos': Number(f.bloqueos_abiertos),
    'Sesiones': Number(f.sesiones),
    '% voz promedio': f.pct_voz_promedio == null ? '—' : Number(f.pct_voz_promedio),
    'Actualizaciones completas': frac(f.actualizaciones_completas, f.actualizaciones_evaluadas),
    'Compromisos cumplidos': frac(f.compromisos_cumplidos, f.compromisos_con_fecha),
    'Observación IA': porId[String(f.usuario_id)] || '',
  },
}));
